draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw compass
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // draw needle
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 40 * Math.cos(t), H/2 + 40 * Math.sin(t));
  ctx.stroke();

  // draw direction lines
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 30 * Math.cos(t + Math.PI/2), H/2 + 30 * Math.sin(t + Math.PI/2));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 30 * Math.cos(t - Math.PI/2), H/2 + 30 * Math.sin(t - Math.PI/2));
  ctx.stroke();

  ctx.restore();
}
